function evaluateExpression(src,vars){const tokens=src.match(/0x[0-9a-f]+|\d+(?:\.\d+)?|[a-z_]\w*|<<|>>|<=|>=|==|!=|&&|\|\||[()+\-*/%&|^<>!~]/gi)||[];if(tokens.join('')!==src.replace(/\s/g,''))throw Error('表达式包含不支持的字符');let k=0;const prec={'||':1,'&&':2,'|':3,'^':4,'&':5,'==':6,'!=':6,'<':7,'>':7,'<=':7,'>=':7,'<<':8,'>>':8,'+':9,'-':9,'*':10,'/':10,'%':10};function atom(){let t=tokens[k++];if(['sin','cos','abs','floor'].includes(t)){if(tokens[k++]!=='(')throw Error('函数后需要括号');let v=expr(1);if(tokens[k++]!==')')throw Error('函数缺少右括号');return ({sin:Math.sin,cos:Math.cos,abs:Math.abs,floor:Math.floor})[t](v)}if(t==='('){let v=expr(1);if(tokens[k++]!==')')throw Error('缺少右括号');return v}if(['-','+','!','~'].includes(t)){let v=atom();return t==='-'?-v:t==='+'?v:t==='!'?+!v:~v}if(Object.hasOwn(vars,t))return vars[t];if(/^(?:0x[\da-f]+|\d+(?:\.\d+)?)$/i.test(t||''))return Number(t);throw Error('未知变量：'+t)}function expr(min){let a=atom();while(prec[tokens[k]]>=min){let op=tokens[k++],b=expr(prec[op]+1);switch(op){case '+':a+=b;break;case '-':a-=b;break;case '*':a*=b;break;case '/':a/=b;break;case '%':a%=b;break;case '&':a&=b;break;case '|':a|=b;break;case '^':a^=b;break;case '<<':a<<=b;break;case '>>':a>>=b;break;case '<':a=+(a<b);break;case '>':a=+(a>b);break;case '<=':a=+(a<=b);break;case '>=':a=+(a>=b);break;case '==':a=+(a===b);break;case '!=':a=+(a!==b);break;case '&&':a=+(!!a&&!!b);break;case '||':a=+(!!a||!!b)}}return a}let n=expr(1);if(k!==tokens.length||!Number.isFinite(n))throw Error('表达式无效或除零');return n}
if(typeof module!=='undefined')module.exports=evaluateExpression;
